contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: depositAmt to send to Deposit, and minSum and logAddr to allow initialization sequence
    function run(uint depositAmt, uint minSum, address logAddr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        // ensure this test contract has enough ETH to perform the deposit
        require(address(this).balance >= depositAmt);

        // configure contract before it gets initialized
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        // observe before-deposit values
        uint beforeHolder = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContract = address(c).balance;

        // perform Deposit sending Ether
        bool depositReverted;
        c.Deposit{value: depositAmt}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            depositReverted = true;
        } else {
            depositReverted = false;
        }

        uint afterHolder = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContract = address(c).balance;

        // General rule: either Deposit reverted and no observable change, or it succeeded and both holder and contract increased by depositAmt
        assert(
            (depositReverted && afterHolder == beforeHolder && afterContract == beforeContract)
            || (!depositReverted && afterHolder == beforeHolder + depositAmt && afterContract == beforeContract + depositAmt)
        );
    }

    receive() external payable { }
}

